import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getDoctorById } from "../services/doctorService";
import { getBookedSlots, bookAppointment } from "../services/appointmentService";
import { isLoggedIn } from "../utils/auth";

function BookAppointment() {
  const { doctorId } = useParams();
  const navigate = useNavigate();

  const [doctor, setDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");
  const [bookedSlots, setBookedSlots] = useState([]);

  // ⚠️ TEMP STATIC (next step → dynamic)
  const timeSlots = ["10:00", "10:10", "10:20", "10:30", "11:00", "11:10"];

  // ✅ FETCH DOCTOR
  useEffect(() => {
    fetchDoctor();
  }, [doctorId]);

  const fetchDoctor = async () => {
    try {
      const res = await getDoctorById(doctorId);
      setDoctor(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  // ✅ FETCH BOOKED SLOTS WHEN DATE CHANGES
  useEffect(() => {
    if (selectedDate) {
      fetchBookedSlots();
    }
  }, [selectedDate]);

  const fetchBookedSlots = async () => {
    try {
      const res = await getBookedSlots(doctorId, selectedDate);
      console.log("BOOKED:", res.data);
      setBookedSlots(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  // ✅ BOOK APPOINTMENT
  const handleBooking = async () => {
    if (!isLoggedIn()) {
      alert("Please login first");
      navigate("/login");
      return;
    }

    if (!selectedDate || !selectedTime) {
      alert("Select date & time");
      return;
    }

    try {
      const payload = {
        userId: 1, // ⚠️ replace with logged user later
        doctorId: Number(doctorId),
        appointmentDate: selectedDate,
        timeSlot: selectedTime,
      };

      const res = await bookAppointment(payload);

      alert("Booking Successful ✅");

      // refresh slots after booking
      fetchBookedSlots();
      setSelectedTime("");

    } catch (err) {
      console.error(err);

      const msg =
        err.response?.data?.message || "Booking failed ❌";

      alert(msg);
    }
  };

  if (!doctor) return <h3>Loading...</h3>;

  return (
    <div style={styles.container}>
      {/* Doctor Info */}
      <div style={styles.card}>
        <img src={doctor.image} alt="doctor" style={styles.image} />
        <h2>{doctor.name}</h2>
        <p>{doctor.specialization}</p>
      </div>

      {/* Booking Section */}
      <div style={styles.booking}>
        <h3>Select Date</h3>
        <input
          type="date"
          onChange={(e) => setSelectedDate(e.target.value)}
        />

        <h3>Select Time</h3>
        <div style={styles.slots}>
          {timeSlots.map((time) => {
            const isBooked = bookedSlots.includes(time);

            return (
              <button
                key={time}
                disabled={isBooked}
                style={
                  isBooked
                    ? styles.disabledSlot
                    : selectedTime === time
                    ? styles.selectedSlot
                    : styles.slot
                }
                onClick={() => !isBooked && setSelectedTime(time)}
              >
                {time}
              </button>
            );
          })}
        </div>

        <button style={styles.bookBtn} onClick={handleBooking}>
          Confirm Booking
        </button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
  },
  card: {
    textAlign: "center",
    marginBottom: "20px",
  },
  image: {
    width: "100px",
    borderRadius: "50%",
  },
  booking: {
    textAlign: "center",
  },
  slots: {
    display: "flex",
    justifyContent: "center",
    gap: "10px",
    flexWrap: "wrap",
    margin: "10px 0",
  },
  slot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  selectedSlot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  disabledSlot: {
    padding: "8px 12px",
    border: "1px solid #ccc",
    background: "#ccc",
    color: "#666",
    cursor: "not-allowed",
    borderRadius: "5px",
  },
  bookBtn: {
    marginTop: "15px",
    padding: "10px 20px",
    background: "green",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default BookAppointment;
